PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS studio (id INTEGER PRIMARY KEY, name TEXT NOT NULL, watermark_text TEXT NOT NULL, sms_sign TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff (id INTEGER PRIMARY KEY, studio_id INTEGER NOT NULL, name TEXT NOT NULL, phone TEXT UNIQUE NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL, FOREIGN KEY(studio_id) REFERENCES studio(id));
CREATE TABLE IF NOT EXISTS package_template (id INTEGER PRIMARY KEY, studio_id INTEGER NOT NULL, name TEXT NOT NULL, FOREIGN KEY(studio_id) REFERENCES studio(id));
CREATE TABLE IF NOT EXISTS package_template_item (id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, quantity INTEGER NOT NULL, sort INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(template_id) REFERENCES package_template(id));
CREATE TABLE IF NOT EXISTS job (id INTEGER PRIMARY KEY, studio_id INTEGER NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', deadline_at TEXT NOT NULL, allow_overage INTEGER NOT NULL DEFAULT 1, overage_unit_price REAL NOT NULL DEFAULT 20, allow_original_download INTEGER NOT NULL DEFAULT 1, overage_settled INTEGER NOT NULL DEFAULT 0, invite_token TEXT UNIQUE NOT NULL, created_by INTEGER, locked_at TEXT, locked_by INTEGER, FOREIGN KEY(studio_id) REFERENCES studio(id));
CREATE TABLE IF NOT EXISTS job_item (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, quantity INTEGER NOT NULL, sort INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(job_id) REFERENCES job(id));
CREATE TABLE IF NOT EXISTS photo (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, filename TEXT NOT NULL, original_key TEXT NOT NULL, preview_key TEXT, thumb_key TEXT, width INTEGER, height INTEGER, sort INTEGER NOT NULL DEFAULT 0, import_status TEXT NOT NULL DEFAULT 'pending', import_error TEXT, FOREIGN KEY(job_id) REFERENCES job(id));
CREATE TABLE IF NOT EXISTS selector (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, permission TEXT NOT NULL, share_selection INTEGER NOT NULL DEFAULT 1, can_change_share INTEGER NOT NULL DEFAULT 1, submitted_at TEXT, overage_accepted INTEGER NOT NULL DEFAULT 0, last_active_at TEXT, UNIQUE(job_id,phone), FOREIGN KEY(job_id) REFERENCES job(id));
CREATE TABLE IF NOT EXISTS selection (selector_id INTEGER NOT NULL, photo_id INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(selector_id,photo_id), FOREIGN KEY(selector_id) REFERENCES selector(id), FOREIGN KEY(photo_id) REFERENCES photo(id));
CREATE TABLE IF NOT EXISTS slot_assignment (id INTEGER PRIMARY KEY, job_item_id INTEGER NOT NULL, slot_index INTEGER NOT NULL DEFAULT 1, photo_id INTEGER NOT NULL, selector_id INTEGER NOT NULL, is_final INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, FOREIGN KEY(job_item_id) REFERENCES job_item(id), FOREIGN KEY(photo_id) REFERENCES photo(id), FOREIGN KEY(selector_id) REFERENCES selector(id));
CREATE TABLE IF NOT EXISTS photo_note (id INTEGER PRIMARY KEY, photo_id INTEGER NOT NULL, selector_id INTEGER, staff_id INTEGER, content TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(photo_id,selector_id));
CREATE TABLE IF NOT EXISTS retouched_photo (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, photo_id INTEGER, filename TEXT NOT NULL, file_key TEXT, thumb_key TEXT, uploaded_by INTEGER);
CREATE TABLE IF NOT EXISTS download_package (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, file_key TEXT, expires_at TEXT);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, actor_type TEXT NOT NULL, actor_id INTEGER NOT NULL, action TEXT NOT NULL, payload TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification (id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL, selector_id INTEGER, kind TEXT NOT NULL, content TEXT NOT NULL, sent_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session (token TEXT PRIMARY KEY, actor_type TEXT NOT NULL, actor_id INTEGER NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS otp_code (phone TEXT PRIMARY KEY, code TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_photo_job ON photo(job_id);
CREATE INDEX IF NOT EXISTS idx_selection_photo ON selection(photo_id);
